package sctp // import "github.com/skill215/diameterkit/adapters/sctp"

Package sctp adapts exclusive one-to-one Linux SCTP message sockets to the
Diameter transport contract. It is an independent, pure-Go module.

CONSTANTS

const SetupStateReserve uint64 = 4096
    SetupStateReserve covers only adapter setup wrappers and synchronization.
    Upstream address/config/socket costs come from its versioned resource query.

const StateReserve uint64 = 4096
    StateReserve covers the adapter value (including prefix/discard/one event),
    constructor option/status copies and bounded synchronization bookkeeping.
    Variable notification/OOB buffers are added, not hidden in this allowance.


VARIABLES

var ErrConcurrentAccept = errors.New("SCTP listener allows one Accept caller")
var ErrConfig = errors.New("invalid SCTP adapter configuration or socket options")

FUNCTIONS

func New(raw *upstream.SCTPConn, cfg Config) (transport.Conn, error)
    New takes exclusive ownership even on failure. The caller must relinquish
    all I/O, options, deadlines and raw-fd access. It verifies message
    mode/options and negotiated streams, clears legacy socket timeouts, and
    takes no address copies. Use Config.Requirements before Node construction;
    Node checks Info before CER/CEA. Use NewDialer/Listen for Node-managed setup
    admission.

func SocketConfig() upstream.SocketConfig
    SocketConfig returns the default socket configuration. Use
    Config.SocketConfig for explicit modes and stream requests before
    transferring ownership to New.


TYPES

type Config struct {
	NotificationMax           int
	NotificationWindow        time.Duration
	MaxNotificationsPerWindow uint32
	StreamMode                StreamMode
	PPIDPolicy                PPIDPolicy
	// Zero selects 1 outbound stream in default mode, 16 in ordered mode,
	// and 16 maximum inbound streams. Actual negotiated counts govern I/O.
	OutboundStreams, MaxInboundStreams uint16
}

func DefaultConfig() Config

func (c Config) Requirements() (transport.Info, error)
    Requirements is a no-I/O query to use before NewNode. Control RX/TX and
    emergency slots are reserved separately by Node and must not be counted
    twice. Kernel queues, Go runtime/allocator/stacks and caller configuration
    are not RSS bounded by this logical ledger. Prebuilt sockets are charged
    from takeover.

func (c Config) SocketConfig() (upstream.SocketConfig, error)

type Dialer struct {
	// Has unexported fields.
}
    Dialer is only the transport.Dialer wrapper. Upstream freezes/validates
    inputs and resolves/connects within the same context; Node owns admission
    and retry.

func NewDialer(network, local, remote string, cfg SetupConfig) (*Dialer, error)

func (d *Dialer) Dial(ctx context.Context) (transport.Conn, error)

func (d *Dialer) Info() transport.Info

type Listener struct {
	// Has unexported fields.
}

func Listen(ctx context.Context, network, address string, cfg SetupConfig) (*Listener, error)
    Listen validates bounded input, resolves and binds one listener. Query
    SetupConfig.Requirements before Node construction. Binding concurrency
    remains caller-owned; Node.Serve owns the listener from admission and
    reserves each passive candidate BEFORE calling Accept. No background accept
    queue is made.

func (l *Listener) Accept(ctx context.Context) (transport.Incoming, error)

func (l *Listener) Addr() net.Addr
    Addr is a bounded frozen bind address (not a dynamic interface enumeration).

func (l *Listener) Close() error

func (l *Listener) Info() transport.ListenerInfo

type ModeInfo struct {
	StreamMode                      StreamMode
	PPIDPolicy                      PPIDPolicy
	InboundStreams, OutboundStreams uint16
	SingleStreamFallback            bool
}
    ModeInfo is an immutable association snapshot. A single-stream fallback has
    ordered head-of-line blocking. Even multi-stream mode retains receive level0
    partial-delivery blocking; this is not a latency or session-order guarantee.

type ModeReporter interface{ SCTPMode() ModeInfo }
    ModeReporter is optionally available on the transport.Conn returned by this
    adapter. It exposes negotiated counts without granting raw socket ownership.

type PPIDPolicy uint8

const (
	// PPID46 sends and accepts only clear-text Diameter PPID46.
	PPID46 PPIDPolicy = iota
	// PPID0Compatibility sends 0 and accepts 0 or 46. It must be selected
	// explicitly for the configured endpoint; received data never changes it.
	// Neither policy accepts DTLS PPID47.
	PPID0Compatibility
)
type SetupConfig struct {
	Transport                                   Config
	MaxAddresses, MaxZoneBytes, MaxAddressBytes int
}
    SetupConfig delegates combined local+remote N/Z/D bounds and owned setup
    to upstream. Every field is explicit; defaults retain the original adapter
    policy.

func DefaultSetupConfig() SetupConfig

func (c SetupConfig) Requirements() (transport.ListenerInfo, error)
    Requirements is a no-I/O upstream ledger query plus adapter-owned storage.
    Listener and every physical candidate are charged independently. Upstream
    scratch is included in its totals; it is never added a second time.

type StreamMode uint8

const (
	UnorderedStream0 StreamMode = iota
	OrderedMultiStream
)

