package tls // import "github.com/skill215/diameterkit/transport/tls"

Package tls performs a bounded TLS handshake on an established TCP socket,
then exposes the shared Diameter stream frame contract. Its optional Dialer
includes TCP/TLS establishment; Listener defers TLS until socket admission.
Neither API loads certificate files.

CONSTANTS

const BufferBytes = streamtransport.BufferBytes
const ListenerBufferBytes = streamtransport.ListenerBufferBytes

TYPES

type Config struct {
	TLS              *stdtls.Config
	HandshakeTimeout time.Duration
}
    Config requires a finite handshake timeout. Node.Dial/Serve additionally
    bound transport and CER/CEA with one absolute deadline. Standalone
    callers own CER/CEA timeout. TLS is cloned; callers must keep shared
    certificate/pool/callback data immutable as required by crypto/tls.Config.
    Callbacks must honor cancellation.

type Conn struct {
	// Has unexported fields.
}
    Conn exposes negotiated TLS state without granting raw socket/deadline
    access. BufferBytes excludes crypto/tls buffers, certificates, caches and
    kernel storage.

func Client(ctx context.Context, conn *net.TCPConn, cfg Config) (*Conn, error)
    Client takes exclusive socket ownership even on failure. ServerName/trust
    and optional mutual authentication are explicit in Config.TLS; there is no
    fallback.

func Server(ctx context.Context, conn *net.TCPConn, cfg Config) (*Conn, error)

func (c *Conn) Close() error

func (c *Conn) ConnectionState() stdtls.ConnectionState

func (c *Conn) DiscardFrame(ctx context.Context, size int) error

func (c *Conn) Info() transport.Info

func (c *Conn) ReadFrameInto(ctx context.Context, dst []byte) error

func (c *Conn) ReadPrefix(ctx context.Context, timeout time.Duration) ([20]byte, error)

func (c *Conn) WriteFrame(ctx context.Context, b []byte) transport.WriteResult

type Dialer struct {
	// Has unexported fields.
}
    Dialer includes the TLS handshake. The caller keeps certificate pools, keys,
    session caches and callback data immutable/concurrency-safe as for Config.

func NewDialer(network, address string, cfg Config) (*Dialer, error)

func (d *Dialer) Dial(ctx context.Context) (transport.Conn, error)

func (d *Dialer) Info() transport.Info

type Listener struct {
	// Has unexported fields.
}
    NewListener takes ownership of raw, including on failure, and freezes
    the top-level TLS configuration. Shared certificate/callback data follows
    Config. TLS runs only in Incoming.Establish, after socket admission by the
    caller.

