package wire // import "github.com/skill215/diameterkit/wire"

Package wire provides bounded byte primitives for generated Diameter codecs.
Views borrow their input for the duration of the enclosing codec operation.

CONSTANTS

const MaxWireSize = 0xffffff

VARIABLES

var (
	ErrFrame  = errors.New("invalid Diameter framing")
	ErrAVP    = errors.New("invalid AVP framing")
	ErrLimit  = errors.New("resource limit exceeded")
	ErrConfig = errors.New("invalid codec limits")
)

FUNCTIONS

func CanonicalRequest(src []byte, l Limits, maxBytes int, fields []CanonicalField, ignoreVSAI bool) ([]byte, error)
    CanonicalRequest returns an owned CanonicalV1 comparison sequence. Top-level
    known keys sort stably between unknown barriers; nested groups stay ordered.
    Header identity excludes HBH/T/E2E. E2E belongs to the duplicate lookup key.

func DecodeBound(n int, l Limits, structureBytes int) (uint64, error)
    DecodeBound estimates retained frame, copied strings, generated structs and
    slice capacity. It is a conservative logical reservation, not a Go heap/RSS
    guarantee. Generated structureBytes includes inline Grouped fields.

func Header(b []byte, l Limits) (pdu.Header, int, error)
func I32(b []byte) (int32, error)
    I32 decodes an exact-width Diameter Integer32, preserving the signed value.

func I64(b []byte) (int64, error)
    I64 decodes an exact-width Diameter Integer64 without float conversion.

func Put24(b []byte, v uint32)
func PutHeader(b []byte, h pdu.Header, n int)
func U32(b []byte) (uint32, error)
func U64(b []byte) (uint64, error)
    U64 decodes an exact-width Diameter Unsigned64 without truncation.

func Uint24(b []byte) uint32

TYPES

type CanonicalField struct {
	PreserveMandatory bool // Only compiled fields with M-dependent semantics.
	Key               avp.Key
	Identity          bool
	Group             []CanonicalField
}
    CanonicalField is a compiled field rule, not a runtime ignore list. Callers
    must validate the original request before applying these comparison rules.
    A nil Group denotes an opaque leaf; grouped fields preserve child sequence.

type DecodeError struct {
	Offset        int
	FrameComplete bool
	Cause         error
}
    DecodeError records framing progress without retaining the input frame.

func (e *DecodeError) Error() string

func (e *DecodeError) Unwrap() error

type Decoder struct {
	// Has unexported fields.
}

func NewDecoder(b []byte, l Limits) *Decoder

func (d *Decoder) Child(b []byte) (*Decoder, error)

func (d *Decoder) Diagnostic(b []byte, groups []avp.Key) (bool, error)
    Diagnostic only scans provably framed headers, with a fixed set of known
    Grouped keys. Malformed quoted lengths end that scan; they do not invalidate
    the enclosing AVP or authorize resynchronizing past untrusted bytes.

func (d *Decoder) Limits() Limits

func (d *Decoder) Next() (View, bool, error)

func (d *Decoder) Remaining() int

type Encoder struct {
	// Has unexported fields.
}
    Encoder uses nil output to measure. Non-nil output is caller-sized and never
    grown.

func NewEncoder(dst []byte, l Limits) *Encoder

func NewReceiveSizer(l Limits) *Encoder
    NewReceiveSizer measures validated received values while ignoring reserved
    flag bits. It cannot write bytes. Sending still uses NewEncoder and Send
    rules.

func (e *Encoder) Address(k avp.Key, f byte, a avp.Address)

func (e *Encoder) BeginGroup(k avp.Key, f byte) GroupMark

func (e *Encoder) Bytes(k avp.Key, f byte, b []byte)

func (e *Encoder) Diagnostic(k avp.Key, flags byte, b []byte, groups []avp.Key)
    Diagnostic encodes quoted bytes without applying application value rules,
    while charging recognized inner headers/depth to the enclosing encoder.

func (e *Encoder) EndGroup(mark GroupMark)

func (e *Encoder) Err() error

func (e *Encoder) Int32(k avp.Key, f byte, v int32)
    Int32 encodes the two's-complement Integer32 representation.

func (e *Encoder) Int64(k avp.Key, f byte, v int64)
    Int64 preserves the complete two's-complement Integer64 representation.

func (e *Encoder) Len() int

func (e *Encoder) Limits() Limits

func (e *Encoder) String(k avp.Key, f byte, s string)

func (e *Encoder) Uint32(k avp.Key, f byte, v uint32)

func (e *Encoder) Uint64(k avp.Key, f byte, v uint64)

type GroupMark struct {
	// Has unexported fields.
}
    GroupMark belongs to the encoder that created it; generated code closes
    groups LIFO.

type Limits struct{ MaxFrameBytes, MaxFieldBytes, MaxAVPs, MaxDepth, MaxRepeated int }

func DefaultLimits() Limits

func (l Limits) Validate() error

type View struct {
	Key    avp.Key
	Flags  byte
	Data   []byte
	Offset int
}

