	Decode         func(*wire.Decoder) (pdu.Body, error)
	Encode         func(*wire.Encoder, pdu.Body) error
	Validate       func(pdu.Body, validation.Mode) error
	Clone          func(pdu.Body) (pdu.Body, error)
